const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text;
if (!raw) throw new Error('Gemini returned no content: ' + JSON.stringify($json).slice(0, 500));
const fields = JSON.parse(raw);
const src = $('Is PDF?').item.json;
return { json: { ...fields, source_file_id: src.id, source_file_name: src.name, model_used: $prevNode.name } };

const inv = $json;
const issues = [];
const required = { vendor: 'Vendor', invoice_number: 'Invoice #', invoice_date: 'Invoice Date', total: 'Total' };
for (const [key, label] of Object.entries(required)) {
  if (inv[key] === null || inv[key] === undefined || inv[key] === '') issues.push(`Missing ${label}`);
}
if (inv.subtotal != null && inv.tax != null && inv.total != null) {
  const expected = Math.round((inv.subtotal + inv.tax) * 100) / 100;
  if (Math.abs(expected - inv.total) > 0.01) {
    issues.push(`Total mismatch: subtotal + tax = ${expected.toFixed(2)}, invoice says ${Number(inv.total).toFixed(2)}`);
  }
}
if (!inv.due_date) issues.push(inv.due_date_note ? `No due date (${inv.due_date_note})` : 'Missing Due Date');
const clean = s => String(s || '').replace(/[^A-Za-z0-9]+/g, '');
const month = inv.invoice_date ? inv.invoice_date.slice(0, 7) : 'UNDATED';
const newName = `${month}_${clean(inv.vendor) || 'UnknownVendor'}_${clean(inv.invoice_number) || 'NOINV'}.pdf`;
return { json: { ...inv, date_processed: new Date().toISOString().slice(0, 10), status: issues.length ? 'Needs Review' : 'OK', notes: issues.join('; '), new_file_name: newName } };
